stSysMenu GetCurMenuItem(void)
{
    u8 CurLayer = stMenu.Layer;
    switch(CurLayer)
    {
        case LAYER1: return stMenu.pL1[stMenu.L1];
        case LAYER2: return stMenu.pL2[stMenu.L2];
        case LAYER3: return stMenu.pL3[stMenu.L3];
        case LAYER4: return stMenu.pL4[stMenu.L4];
        default: break;
    }
    return stMenu.pL1[stMenu.L1];
}

