MenuItemStepAlgo.code:
void MenuItemStepAlgo(u8 *Choose, u8 *Cursor, u8 MenuItemNum, u8 MaxDispNum, s8 Step, bool Is_Loop)
{
    if(MenuItemNum < 2)
    {
        return;
    }
    MaxDispNum = MenuItemNum < MaxDispNum ? MenuItemNum : MaxDispNum;
    *Cursor = NumStep(*Cursor, Step > 0 ? (MaxDispNum - 1) : 0, abs(Step));
    if(Is_Loop)
    {
        *Choose = NumLoopStep(*Choose, 0, MenuItemNum - 1, Step);
        if(*Choose == 0 && Step > 0)
        {
            *Cursor = 0;
        }
        if(*Choose == (MenuItemNum - 1) && Step < 0)
        {
            *Cursor = MaxDispNum - 1;
        }
    }
    else
    {
        *Choose = NumStep(*Choose, Step > 0 ? (MenuItemNum - 1) : 0, abs(Step));
    }
}

MenuItemChooseAlgo.code:
void MenuItemChooseAlgo(u8 *Cursor, u8 Choose, u8 MenuItemNum, u8 MaxDispNum)
{
    if(MenuItemNum < MaxDispNum)
    {
        *Cursor = Choose;
    }
    else if(Choose + MaxDispNum - 1 < MenuItemNum)
    {
        *Cursor = 0;
    }
    else
    {
        *Cursor = MaxDispNum - 1 - (MenuItemNum - Choose - 1);
    }
}

