ParaEditRender.code:
void ParaEditRender(void)
{
    u8 ParaNum = ParaEdit.ParaNum;
    char **Paras = ParaEdit.Paras;
    char *Title = ParaEdit.Title;
    u8 Choose = ParaEdit.Choose;
    u8 Cursor = ParaEdit.Cursor;

    DISP_TITLE(Title);
    MENU_AREA_CLEAR();
    GUI_SetTextMode(GUI_TEXTMODE_NORMAL);
    GUI_SetColor(GUI_MENUITEM_TEXT_COLOR);
    for(u8 i = Choose - Cursor, j = 0; i < Choose - Cursor + C_MAX && i < ParaNum; i++, j++)
    {
        char *Para = Paras[i];
        GUI_SetBkColor(Cursor == j ? GUI_CURSOR_COLOR : GUI_MENUBACK_COLOR);
        GUI_DispStringAtCEOL(Para, 0, MENU_TITLE_HEIGHT + j * MENU_ITEM_HEIGHT);
    }
}

