L1Display.code:
void L1Display(void)
{
    typedef struct
    {
        u8 x;
        u8 y;
        GUI_CONST_STORAGE GUI_BITMAP *Image;
        GUI_CONST_STORAGE GUI_BITMAP *Image_R;
        u8 TextX;
        u8 TextY;
        char *Text;
    } Render_Data_t;
    // clang-format off
	const Render_Data_t Data[]=
	{
		{.x=10,.y=7,.Image=&bmMainMenu_DMX,.Image_R=&bmMainMenu_DMX_R,.TextX=12,.TextY=50,.Text="DMX"},
		{.x=60,.y=7,.Image=&bmMainMenu_Personality,.Image_R=&bmMainMenu_Personality_R,.TextX=64,.TextY=50,.Text="Pers"},
		{.x=110,.y=7,.Image=&bmMainMenu_Programs,.Image_R=&bmMainMenu_Programs_R,.TextX=114,.TextY=50,.Text="Prog"},
		{.x=10,.y=68,.Image=&bmMainMenu_Manul,.Image_R=&bmMainMenu_Manul_R,.TextX=10,.TextY=112,.Text="Manu"},
		{.x=60,.y=68,.Image=&bmMainMenu_Info,.Image_R=&bmMainMenu_Info_R,.TextX=67,.TextY=112,.Text="Info"},
	};
    // clang-format on
    for(u8 i = 0; i < sizeof(Data) / sizeof(Render_Data_t); i++)
    {
        if(stMenu.C1 == i)
        {
            GUI_DrawBitmap(Data[i].Image_R, Data[i].x, Data[i].y);
            GUI_SetBkColor(rgb565_to_rgb888(WHITE));
            GUI_ClearRect(Data[i].x, Data[i].y + Data[i].Image_R->YSize, Data[i].x + Data[i].Image_R->XSize - 1,
                          Data[i].y + Data[i].Image_R->YSize + GUI_GetFontDistY() + (i == 2 ? 2 : 0));
            stLcd.BackColor = WHITE;
            stLcd.PointColor = BLACK;
        }
        else
        {
            GUI_DrawBitmap(Data[i].Image, Data[i].x, Data[i].y);
            GUI_SetBkColor(rgb565_to_rgb888(BLACK));
            GUI_ClearRect(Data[i].x, Data[i].y + Data[i].Image->YSize, Data[i].x + Data[i].Image->XSize - 1,
                          Data[i].y + Data[i].Image_R->YSize + GUI_GetFontDistY() + (i == 2 ? 2 : 0));
            stLcd.BackColor = BLACK;
            stLcd.PointColor = WHITE;
        }
        GUI_SetTextMode(GUI_TM_NORMAL);
        GUI_SetColor(rgb565_to_rgb888(stLcd.PointColor));
        GUI_SetBkColor(rgb565_to_rgb888(stLcd.BackColor));
        GUI_DispStringAt(Data[i].Text, Data[i].TextX, Data[i].TextY);
        //LCD_DISP_STRING_M1(Data[i].TextX, Data[i].TextY, Data[i].Text);
    }

    stLcd.BackColor = MENUBACKCOLOR;
    stLcd.PointColor = WHITE;
}

