L2FixSetDisp.code:
void L2FixSetDisp(void)
{
    u8 i;
    //	DecToAscii(stPara.Inten,stMemData->Intensity,2);
    DecToAscii(stPara.Sensi, stMemData->Sensitivity, 3);
    DecToAscii(stPara.wChannel, stMemData->WirelessCh, 2);
    DecToAscii(stPara.CodeFac, stMenu.PasswordFac, 3);
    DecToAscii(stPara.CodeCal, stMenu.Password, 3);
    for(i = 0; i < C_MAX; i++)
    {
        if(i + stMenu.T2 < 8)
        {
            u8 Offset = i + stMenu.T2 > 1 ? i + stMenu.T2 - 1 : i + stMenu.T2;
            if(i + stMenu.T2 != 7 && i + stMenu.T2 != 1)
            {
                stMenu.pL2[i + stMenu.T2].Para =
                  *(*(NameFixSet + i + stMenu.T2) + mLANGUAGE * stMenu.pL2[i + stMenu.T2].Num +
                    (*(&stMemData->PriSec + Offset)));
            }
        }
        else
        {
            if(i + stMenu.T2 < 10)
            {
                stMenu.ParaVal = 0;
                stMenu.pL2[i + stMenu.T2].Para = *(pnYesNo + stMenu.ParaVal + 2 * mLANGUAGE);
            }
        }
        MenuItemDisp(stMenu.pL2[i + stMenu.T2].Name[mLANGUAGE], i, stMenu.C2 == i);
        ParaDisp(stMenu.pL2[i + stMenu.T2].Para != NULL ? stMenu.pL2[i + stMenu.T2].Para : "", i, stMenu.C2 == i);
    }
}

