L3SensorDisp.code:
void L3SensorDisp(void)
{
    ErrorNum = 0;
    stLcd.PointColor = RED;
    if(stCom.StateField & 0x03) //有报错
    {
        u8 i;
        for(i = 0; i < ERRORNUM; i++) //错误标志位扫描
        {
            if(stCom.StateField & (0x00000001 << i))
            {
                ErrorIndex[ErrorNum++] = i; //记录错误下标号
            }
        }

        //错误信息字体：高：16 宽：8, x1 = 54+20 = 74; x2 = 54+20+80+20 = 174; y = 46
        for(i = 0; i < ErrorNum; i++)
        {
            LCD_DISP_STRING_M0(0, Ym[i], *(ErrorName + ErrorIndex[i] + ERRORNUM * mLANGUAGE));
        }
        stLcd.PointColor = WHITE;
    }
    else
    {
        //x = 0+(160-19*8)/2 = 4; y = 0+(128-16)/2 = 56
        LCD_DISP_STRING_M0(4, 56, "All Sensors are ok!");
    }
    stLcd.PointColor = WHITE;
}

