    //LCD_DISP_STRING_M1(stMenu.pL2[4].Xp[mLANGUAGE], Ym[4], pnRunMode[stMemData->Prog]);
    MenuItemDisp(*(stMenu.pL2[4].Name + mLANGUAGE), 4, 0);
