    }

    //LCD_DISP_STRING_M1(0, Ym[5], *(stMenu.pL2[5].Name + mLANGUAGE));
    sprintf(StrBuf, "%03dF", stTemp.TempValF);
    //LCD_DISP_STRING_M1(stMenu.pL2[5].Xp[mLANGUAGE], Ym[5], StrBuf);
    MenuItemDisp(*(stMenu.pL2[5].Name + mLANGUAGE), 5, 0);
    ParaDisp(StrBuf, 5, 0);
}

