AriaResend.code:
void AriaResend(u8 Order)
{
    switch(Order)
    {
            /*  case PAGE_ARIA_ENABLE_ARIA:
                 stAriaPara.WdmxEn = stMemData->AriaSetting[ARIA_SETTING_ARIA_EN] == ARIA_ON;
                 stAriaPara.WdmxType = stMemData->AriaSetting[ARIA_SETTING_ARIA_FREQ];
                 AriaTxSetGetWaitRx(TYPE_REQ_SET_WDMX);
                 break; */
        case PAGE_ARIA_FREQ:
            stAriaPara.WdmxEn = stMemData->AriaSetting[ARIA_SETTING_ARIA_EN] == ARIA_ON;
            stAriaPara.WdmxType = stMemData->AriaSetting[ARIA_SETTING_ARIA_FREQ];
            AriaTxSetGetWaitRx(TYPE_REQ_SET_WDMX);
            break;
        case PAGE_ARIA_CH_24:
            stAriaPara.W24gCh = stMemData->AriaSetting[ARIA_SETTING_CH24];
            AriaTxSetGetWaitRx(TYPE_REQ_SET_W24G);
            break;
        case PAGE_ARIA_CH_900:
            stAriaPara.SubGhzCh = stMemData->AriaSetting[ARIA_SETTING_CH900];
            AriaTxSetGetWaitRx(TYPE_REQ_SET_SUB_GHZ_CH);
            break;
        case PAGE_ARIA_MESH:
            stAriaPara.MeshEnable = stMemData->AriaSetting[ARIA_SETTING_MESH] == ARIA_MESH_ON;
            AriaTxSetGetWaitRx(TYPE_REQ_SET_MESH_ENABLE);
            break;
        case PAGE_ARIA_ENABLE_BLUE:
            stAriaPara.BluetoothEn = stMemData->AriaSetting[ARIA_SETTING_BLUE_EN] == ARIA_BLUE_ON;
            AriaTxSetGetWaitRx(TYPE_REQ_SET_BLUETOOTH);
            break;
        default: break;
    }
}

