void L3FixSetM(void)
{
    if(!FIXSET_IS_NUM3)
    {
        stMenu.ParaVal = ParaEdit.Choose;
        stMenu.SaveVal = ParaEdit.ValMem;
    }
    if(stMenu.ParaVal == stMenu.SaveVal)
    {
        stKey.SaveFlag = 0;
        stLcd.BackColor = MENUBACKCOLOR;
        L2_Refresh();
        return;
    }

    if(stKey.SaveFlag)
    {
        stKey.SaveFlag = 0;
        u8 Offset = stMenu.L2 > 1 ? stMenu.L2 - 1 : stMenu.L2;
        *(&stMemData->PriSec + Offset) = stMenu.ParaVal;
        MemWriteNewData(MEM_TAG_PRI_SEC + Offset, stMenu.ParaVal);

        if(!stMenu.L2) stDim.RunMode = stMemData->PriSec;
        if(stMenu.L2 == 5)
        {
            stKey.FlipDisp = stMenu.ParaVal;
            Lcd_Display_Set(stKey.FlipDisp);
            stLcd.BackColor = BLACK;
            stLcd.PointColor = WHITE;
            //LCD_ClearScreen(MENUBACKCOLOR);                                    //清屏
            //LCD_FillColor(0, 0, 160, 16, BLACK);                               //黑色背景区域
            //LCD_DISP_STRING_H1(Hx, Hy, stMenu.pL1[stMenu.L1].Name[mLANGUAGE]); //显示标题信息
            DISP_TITLE(stMenu.pL1[stMenu.L1].Name[mLANGUAGE]);
            stLcd.BackColor = MENUBACKCOLOR;
            //LCD_DISP_CURSOR(Ym[stMenu.C2]); //显示第一行光标
            L2FixSetDisp();
        }
        /* if(stMenu.L2 == 7)
        {
            if(!stMemData->WirelessSig)
            {
                stAriaPara.WdmxEn = 0;
                stAriaPara.W24gCh = stMemData->WirelessCh;
                AriaReqDispose(TYPE_REQ_SET_W24G);
            }
            else
            {
                stAriaPara.WdmxEn = 1;
                stAriaPara.WdmxType = 0;
                AriaReqDispose(TYPE_REQ_SET_WDMX);
            }
        } */
        /* if(stMenu.L2 == 8 && !stMemData->WirelessSig)
        {
            stAriaPara.W24gCh = stMemData->WirelessCh;
            AriaReqDispose(TYPE_REQ_SET_W24G);
        } */
    }
    else
    {
        if(stMenu.L2 != 7)
        {
            stMenu.pL2[stMenu.L2].Para =
              *(*(NameFixSet + stMenu.L2) + stMenu.SaveVal + mLANGUAGE * stMenu.pL2[stMenu.L2].Num);
        }
        else
        {
            if(stMenu.L2 == 7)
            {
                DecToAscii(stMenu.pL2[stMenu.L2].Para, stMenu.SaveVal, 3);
            }
            else
            {
                DecToAscii(stMenu.pL2[stMenu.L2].Para, stMenu.SaveVal, 2);
            }
        }
    }
    stLcd.PointColor = WHITE;
    stLcd.BackColor = MENUBACKCOLOR;
    L2_Refresh();
}

