void KeyDispose_Enter(void) //Enter键
{
    switch(stMenu.Layer)
    {
        case LAYER1:
            stMenu.Layer = LAYER2;
            stMenu.pL2 = stMenu.pL1[stMenu.L1].Next;
            stMenu.pL1[stMenu.L1].KeyEnter();
            break;

        case LAYER2:
            if(stMenu.LayerSpecFlag) return;
            stMenu.Layer = LAYER3;
            stMenu.pL3 = stMenu.pL2[stMenu.L2].Next;
            stMenu.pL2[stMenu.L2].KeyEnter();
            break;

        case LAYER3:
            stMenu.Layer = LAYER4;
            stMenu.pL4 = stMenu.pL3[stMenu.L3].Next;
            stMenu.pL3[stMenu.L3].KeyEnter();
            break;

        default: break;
    }
}

