KeyCalculate.code:
u8 KeyCalculate(u8 KeyType)
{
    if(KeyType == BIT_NONE) return KEY_NONE;
    switch(KeyType)
    {
        case BIT_ENTER:
            if(stKey.SaveFlag)
                return KEY_BACK;
            else
                return KEY_ENTER;
        case BIT_BACK: stKey.SaveFlag = 0; return KEY_BACK;
        case BIT_TOP: return KEY_TOP;
        case BIT_BOTTOM: return KEY_BOTTOM;
        default: return KEY_NONE;
    }
}

