KeyValDispose.code:
u8 KeyValDispose(void)
{
    if(!stKey.KeyCnt)
    {
        stKey.JitterCnt = 0;
        stKey.LongPress = 0;
        return KEY_NONE;
    }

    if(!(stKey.JitterCnt++))
    {
        stKey.BkpKeyTrg = stKey.KeyTrg;
        return KEY_NONE;
    }

    if(stMenu.RTDisplay == RT_TIME)
    {
        if(stKey.KeyCnt == BIT_ENTER)
        {
            if(stKey.LongPress++ > 250)
            {
                stKey.LongPress = 0;
                stMenu.RTAlter = RT_TIME;
            }
        }
    }

    if(stKey.FastFlag == KEY_SP_FAST) //按键快速处理--用于数值加减
    {
        if(stKey.LongPress++ > 33) return KeyCalculate(stKey.KeyCnt);
    }

    if(stKey.FastFlag == KEY_SP_SLOW) //慢速按键处理--用于菜单条上下滚动
    {
        if(stKey.LongPress++ > 33)
        {
            static u8 Cnt = 0;
            if(++Cnt & 0x07) return KEY_NONE;
            Cnt = 0;
            return KeyCalculate(stKey.KeyCnt);
        }
    }

    stKey.KeyTrg ^= stKey.BkpKeyTrg;
    stKey.BkpKeyTrg = 0;
    return KeyCalculate(stKey.KeyTrg);
}

KeyFunction.code:
void KeyFunction(void)
{
    u8 KeyVal;
    if(!Timer[TIMER_KEY_SCAN].TFlag) return;
    SoftTimerOpen(TIMER_KEY_SCAN, TIME_20MS);

    KeyScan();
    if((KeyVal = KeyValDispose()) == KEY_NONE)
    {
        LEDA_Black();
        return;
    }

    stTime.LedaBlackCnt = 30;
    SoftTimerOpen(TIMER_LEDA_KEY, TIME_2S);

    if(stKey.LedaState != LED_ON)
    {
        LEDA_ON;
        stKey.LedaState = LED_ON;
        return;
    }
    if(KeyVal < KEY_NONE)
    {
        stKey.FlipDisp ? DispRevertKeyDispose[KeyVal]() : KeyDispose[KeyVal]();
    }
}
